SELECT I.ID, C.NOME_CRITERIO AS CRITERIO, ROUND(I.VALOR_UNITARIO, 2) AS VALOR_UNITARIO, ROUND(I.QUANTIDADE, 3) AS QUANTIDADE_TON, ROUND(I.VALOR_TOTAL_ITEM, 2) AS VALOR_TOTAL FROM ITEM_LANCAMENTO I JOIN CRITERIO_COBRANCA C ON I.ID_CRITERIO = C.ID JOIN LANCAMENTO_ARMAZENAGEM L ON I.ID_LANCAMENTO = L.ID WHERE L.CODPARC = :VAR_PARCEIRO_SELECIONADO AND DATE_FORMAT(L.DT_LANCAMENTO, '%Y-%m') = :VAR_MES_SELECIONADO AND I.ORIGEM = 'Manual' ORDER BY C.NOME_CRITERIO